registerHooks({resolve(s,c,n){if(s.endsWith(\".js\") && c.parentURL?.startsWith(\"file:\")){const u=new URL(s.replace(/\\.js"'$/,".ts"),c.parentURL);if(existsSync(fileURLToPath(u)))return n(u.href,c);}return n(s,c);}});
const {priceWithCoupons:p,CouponError}=await import("./src/pricing/coupon.ts");
const item=(unitPrice,quantity=1,sku="A")=>({sku,name:sku,unitPrice,quantity});
const order=(type,value,extra={})=>({scope:"order",type,value,...extra});
const ic=(type,value,extra={})=>({scope:"item",sku:"A",type,value,...extra});
let count=0;
function test(name,fn){try{fn();count++;console.log("PASS "+name);}catch(e){console.log("FAIL "+name+": "+e.message);process.exitCode=1;}}
function discount(items,coupons,expected){assert.equal(p(items,coupons).discount,expected);}
test("1 rate truncation and boundaries",()=>{discount([item(101)],[order("rate",33)],33);discount([item(101)],[order("rate",1)],1);discount([item(101)],[order("rate",100)],101);});
test("2 fixed cap, zero base",()=>{discount([item(100)],[order("fixed",200)],100);discount([item(0)],[ic("fixed",200)],0);});
test("3 maxDiscount rate/fixed/zero",()=>{for(const type of ["rate","fixed"]){discount([item(1000)],[order(type,50,{maxDiscount:20})],20);discount([item(1000)],[ic(type,50,{maxDiscount:0})],0);}});
test("4 minOrder below/equal/above",()=>{for(const coupon of [ic,order]){discount([item(1000)],[coupon("fixed",100,{minOrder:1001})],0);discount([item(1000)],[coupon("fixed",100,{minOrder:1000})],100);discount([item(1000)],[coupon("fixed",100,{minOrder:999})],100);}});
test("4 original subtotal after item discount",()=>discount([item(1000)],[ic("fixed",800),order("fixed",100,{minOrder:1000})],900));
test("5 line amount once, rate rounding and fixed",()=>{discount([item(101,3)],[ic("rate",50)],151);discount([item(101,3)],[ic("fixed",100)],100);});
test("6,7 item first, order base, permutations",()=>{const items=[item(1000),item(2000,1,"B")], coupons=[ic("fixed",500),ic("rate",50,{sku:"B"}),order("rate",10)];discount(items,coupons,1650);assert.deepEqual(p(items,coupons),p(items,[coupons[2],coupons[1],coupons[0]]));});
test("8 duplicate item/order, absent SKU even if ineligible",()=>{for(const coupons of [[ic("fixed",1),ic("fixed",1)],[order("fixed",1),order("fixed",1)],[ic("fixed",1,{sku:"missing"})],[ic("fixed",1,{minOrder:9999}),ic("fixed",1,{minOrder:9999})],[order("fixed",1,{minOrder:9999}),order("fixed",1,{minOrder:9999})],[ic("fixed",1,{sku:"missing",minOrder:9999})]])assert.throws(()=>p([item(100)],coupons),CouponError);});
test("9 invalid values and missing SKU",()=>{for(const value of [0,-1,1.5,101,NaN,Infinity])assert.throws(()=>p([item(100)],[order("rate",value)]),CouponError);for(const value of [0,-1,1.5,NaN,Infinity])assert.throws(()=>p([item(100)],[order("fixed",value)]),CouponError);for(const field of ["maxDiscount","minOrder"])for(const value of [-1,1.5,NaN,Infinity])assert.throws(()=>p([item(100)],[order("fixed",1,{[field]:value})]),CouponError);assert.throws(()=>p([item(100)],[{scope:"item",type:"fixed",value:1}]),CouponError);discount([item(100)],[order("fixed",1,{minOrder:0,maxDiscount:0})],0);});
test("10 discount sum and shipping post all discounts",()=>{assert.deepEqual(p([item(60000)],[ic("fixed",5000),order("fixed",5000)]),{subtotal:60000,discount:10000,shipping:0,total:50000});assert.deepEqual(p([item(60000)],[ic("fixed",5000),order("fixed",5001)]),{subtotal:60000,discount:10001,shipping:3000,total:52999});assert.deepEqual(p([item(100)],[order("fixed",100)]),{subtotal:100,discount:100,shipping:3000,total:3000});});
test("11 empty skips invalid, duplicate, absent coupons",()=>{assert.deepEqual(p([],[{scope:"item",type:"rate",value:0},order("fixed",1),order("fixed",1)]),{subtotal:0,discount:0,shipping:0,total:0});const coupons=new Proxy([],{get(){throw Error("coupon touched");}});assert.deepEqual(p([],coupons),{subtotal:0,discount:0,shipping:0,total:0});});
test("12 frozen arrays and elements unchanged",()=>{const items=Object.freeze([Object.freeze(item(1000,2)),Object.freeze(item(100,1,"B"))]);const coupons=Object.freeze([Object.freeze(order("rate",10)),Object.freeze(ic("fixed",100))]);const before=JSON.stringify({items,coupons});assert.deepEqual(p(items,coupons),{subtotal:2100,discount:300,shipping:3000,total:4800});assert.equal(JSON.stringify({items,coupons}),before);});
console.log("Total passed: "+count);
